SELECT sl.id, sl.create_user_id, sl.create_user_name, sl.create_time, sl.update_user_id, sl.update_user_name, sl.update_time, sl.version, sl.is_deleted, sl.user_id, sl.user_name, sl.dept_id, sl.dept_name, sl.sku_no, sl.product_name, sl.use_user_id, sl.use_user_name, sl.qty, sl.sku_id FROM sample_ledger sl WHERE ${params.sqlMap.default} AND sl.is_deleted = false
AND sl.qty != 0
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sl.create_time DESC

SELECT sl.id, sl.create_user_id, sl.create_user_name, sl.create_time, sl.update_user_id, sl.update_user_name, sl.update_time, sl.version, sl.is_deleted, sl.user_id, sl.user_name, sl.dept_id, sl.dept_name, sl.sku_no, sl.product_name, sl.use_user_id, sl.use_user_name, sl.qty, sl.sku_id FROM sample_ledger sl WHERE ${params.sqlMap.default} AND sl.is_deleted = false
AND sl.qty != 0
AND sl.id in
#{item}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
